(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const catalogue=JSON.parse($('kp-education-profession-data').textContent),unique=x=>[...new Set(x)],list=x=>x.length?x.join(', '):'—';
function analyze(model,cusp,rules=catalogue.rules){if(!model?.ready)return {ready:false,reason:'Complete the natal planet positions and all twelve cusps.'};const house=model.houses.find(h=>h.id===cusp);if(!house)return {ready:false,reason:'Selected natal cusp is unavailable.'};const sub=model.planets.find(p=>p.id===house.sl);if(cusp===9)return {ready:true,cusp,house,lord:sub?.id,occupiedHouse:sub?.occ,higherStreams:window.KPHigherEducationData?.[sub?.id]};const ids=unique([house.sgl,house.stl,house.sl,sub?.stl,sub?.sl,...(house.occ||[])].filter(Boolean));const points=ids.map(id=>model.planets.find(p=>p.id===id)).filter(Boolean);const signs=unique([house.signIndex,...points.map(p=>p.signIndex)]);const rows=ids.map(id=>model.fourfold.planets.find(p=>p.id===id)).filter(Boolean);const houses=unique(rows.flatMap(row=>['A','B','C','D'].flatMap(k=>row[k]||[]))).sort((a,b)=>a-b);
const matches=rules.map(rule=>{const planets=rule.planets.filter(p=>ids.includes(p)),rashi=rule.signs.filter(s=>signs.includes(s)),bhava=rule.houses.filter(h=>houses.includes(h));const factors=[planets.length>0,rashi.length>0,bhava.length>0],complete=rule.planets.every(p=>ids.includes(p))&&rule.signs.every(s=>signs.includes(s))&&rule.houses.every(h=>houses.includes(h))&&!rule.review;return {rule,planets,rashi,houses:bhava,complete,factors:factors.filter(Boolean).length,coverage:planets.length/rule.planets.length+rashi.length/rule.signs.length+bhava.length/rule.houses.length};}).filter(m=>m.factors===3).sort((a,b)=>Number(b.complete)-Number(a.complete)||a.rule.review-b.rule.review||b.coverage-a.coverage||a.rule.id-b.rule.id);return {ready:true,cusp,house,ids,points,rows,signs,houses,matches};}
function evidence(d){return '<table class="ed-table"><thead><tr><th>Layer / planet</th><th>Rashi</th><th>Star / Sub</th><th>Significator houses</th></tr></thead><tbody>'+d.points.map(p=>{const row=d.rows.find(r=>r.id===p.id);return '<tr><th>'+esc(p.id)+'</th><td>'+esc(p.signCode)+'</td><td>'+esc(p.stl)+' / '+esc(p.sl)+'</td><td>'+esc(list(unique(['A','B','C','D'].flatMap(k=>row?.[k]||[])).sort((a,b)=>a-b)))+'</td></tr>';}).join('')+'</tbody></table>';}
function higherHTML(d){const lang=window.KPPreferences?.get?.().language||'english',rows=[];for(const selected of lang==='bilingual'?['english','marathi']:[lang]){if(!['english','marathi'].includes(selected))continue;const mr=selected==='marathi',text=d.higherStreams?.[mr?1:0]?.[d.occupiedHouse-1]||(mr?'या ग्रहासाठी उच्च शिक्षणाची स्वतंत्र शाखा दिलेल्या तक्त्यात उपलब्ध नाही.':'No higher-education stream was supplied for this planet.');rows.push('<article class="ed-result" data-education-cusp="9" data-no-localize lang="'+(mr?'mr':'en')+'"><h3>'+(mr?'उच्च शिक्षण':'Higher education')+'</h3><p>'+esc(text)+'</p></article>');}return rows.join('');}
function resultHTML(d){if(!d.ready)return '<p>'+esc(d.reason)+'</p>';if(d.cusp===9)return higherHTML(d);const title=d.cusp===4?'Basic education · 4th house':d.cusp===9?'Higher education · 9th house':'Profession · 10th house';const top=d.matches[0];return '<article class="ed-result" data-education-cusp="'+d.cusp+'"><h3>'+title+'</h3><p>Cusp: '+esc(d.house.signCode)+' '+esc(d.house.degree)+' · SGL '+esc(d.house.sgl)+' · STL '+esc(d.house.stl)+' · CSL '+esc(d.house.sl)+'</p>'+evidence(d)+'<p class="ed-summary">'+(top?'Best matching branch: '+esc(top.rule.title):'No branch has matching planet, sign and house factors for this selected house.')+'</p><p>Combined significators: '+esc(list(d.houses))+'</p>'+d.matches.slice(0,8).map(m=>'<div class="ed-match" data-education-rule="'+m.rule.id+'"><h4>'+esc(m.rule.title)+'</h4><p>'+(m.complete?'All listed factors present':m.rule.review?'Partial match · additional conditions need review':'Partial match')+'</p><p>Matched planets: '+esc(list(m.planets))+' · Rashi: '+esc(list(m.rashi.map(i=>['Ar','Ta','Ge','Ca','Le','Vi','Li','Sc','Sg','Cp','Aq','Pi'][i])))+' · Houses: '+esc(list(m.houses))+'</p><details><summary>Matching factors and missing evidence</summary><p>Planets: '+esc(m.rule.planetRaw)+'<br>Signs: '+esc(m.rule.signRaw)+'<br>Houses: '+esc(m.rule.houseRaw)+'</p><p>Missing planets: '+esc(list(m.rule.planets.filter(p=>!m.planets.includes(p))))+'; missing signs: '+esc(list(m.rule.signs.filter(s=>!m.rashi.includes(s)).map(i=>['Ar','Ta','Ge','Ca','Le','Vi','Li','Sc','Sg','Cp','Aq','Pi'][i])))+'; missing houses: '+esc(list(m.rule.houses.filter(h=>!m.houses.includes(h))))+'</p></details></div>').join('')+'</article>';}
function refresh(){const entered=Number($('ed-category')?.value),cusp=[4,9,10].includes(entered)?entered:4,data=[analyze(window.currentKPModel,cusp)];if($('ed-results'))$('ed-results').innerHTML=data.map(resultHTML).join('');return data;}
function snapshot(){const data=refresh();return '<div class="ed-report"><p>Native: '+esc($('name')?.value)+' · '+esc($('dob')?.value)+' '+esc($('birthTime')?.value)+'</p><p>'+esc($('ed-category')?.selectedOptions[0]?.textContent||'4th house · Basic education')+'</p>'+data.map(resultHTML).join('')+'</div>';}
window.KPEducationProfession=Object.freeze({analyze,refresh,snapshot,getCatalogue:()=>JSON.parse(JSON.stringify(catalogue))});function init(){const section=$('education-profession');section.innerHTML='<article class="card"><div class="ed-toolbar"><label for="ed-category">Select house<select id="ed-category"><option value="4">4th house · Basic education</option><option value="9">9th house · Higher education</option><option value="10">10th house · Profession</option></select></label><button id="education-profession-preview" type="button">Preview · Print / Save PDF</button></div><div id="ed-results" class="ed-results"></div></article>';$('ed-category').addEventListener('change',refresh);$('education-profession-preview').addEventListener('click',()=>KPReportPreview.open('education-profession'));new MutationObserver(()=>{if(section.classList.contains('active'))refresh();}).observe(section,{attributes:true,attributeFilter:['class']});const status=$('kp-status');if(status)new MutationObserver(()=>{if(section.classList.contains('active'))refresh();}).observe(status,{childList:true});refresh();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
